import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { Icon, type IconName } from "./icon";

import controlStyles from "./controls.module.css";

const Empty = React.forwardRef<React.ComponentRef<"div">, React.ComponentPropsWithoutRef<"div">>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        data-slot="empty"
        className={cn(
          "flex w-full min-w-0 flex-1 flex-col items-center justify-center gap-4 rounded-xl border-dashed p-6 text-center text-balance",
          className
        )}
        {...props}
      />
    );
  }
);
Empty.displayName = "Empty";

const EmptyHeader = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="empty-header"
      className={cn("flex max-w-sm flex-col items-center gap-2", className)}
      {...props}
    />
  );
});
EmptyHeader.displayName = "EmptyHeader";

const emptyMediaVariants = cva(
  "mb-2 flex shrink-0 items-center justify-center [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        icon: "flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted text-foreground [&_svg:not([class*='size-'])]:size-4"
      }
    },
    defaultVariants: {
      variant: "default"
    }
  }
);

const EmptyMedia = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div"> & VariantProps<typeof emptyMediaVariants>
>(({ className, variant = "default", ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="empty-media"
      data-variant={variant}
      className={cn(emptyMediaVariants({ variant, className }))}
      {...props}
    />
  );
});
EmptyMedia.displayName = "EmptyMedia";

const EmptyTitle = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="empty-title"
      className={cn(controlStyles.sectionTitle, className)}
      {...props}
    />
  );
});
EmptyTitle.displayName = "EmptyTitle";

function EmptyDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <div
      data-slot="empty-description"
      className={cn(
        controlStyles.supporting,
        "text-muted-foreground [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className
      )}
      {...props}
    />
  );
}

const EmptyContent = React.forwardRef<
  React.ComponentRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => {
  return (
    <div
      ref={ref}
      data-slot="empty-content"
      className={cn(
        "flex w-full max-w-sm min-w-0 flex-col items-center gap-2.5 text-sm text-balance",
        className
      )}
      {...props}
    />
  );
});
EmptyContent.displayName = "EmptyContent";

export { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle };

export const EmptyState = ({
  title,
  description,
  actions,
  icon = "inbox",
  variant = "default"
}: {
  title: string;
  description?: string;
  actions?: React.ReactNode;
  icon?: IconName;
  variant?: "default" | "compact";
}) =>
  variant === "compact" ? (
    <div
      role="status"
      data-slot="empty-state"
      data-variant="compact"
      className="flex flex-wrap items-center gap-2"
    >
      <Icon name={icon} />
      <span>{title}</span>
      {actions}
    </div>
  ) : (
    <Empty data-slot="empty-state" data-variant="default">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <Icon name={icon} />
        </EmptyMedia>
        <EmptyTitle>{title}</EmptyTitle>
        {description && <EmptyDescription>{description}</EmptyDescription>}
      </EmptyHeader>
      {actions && <EmptyContent>{actions}</EmptyContent>}
    </Empty>
  );

.field {
  --v4-field-height: var(--v4-size-control-sm);
  --v4-field-inline: var(--v4-space-control-inline-sm);
  --v4-field-nested: var(--v4-size-nested-sm);
  box-sizing: border-box;
  min-height: var(--v4-field-height);
  padding-block: calc(
    (var(--v4-field-height) - var(--v4-type-body-line-height)) / 2 - var(--v4-size-control-border)
  );
  padding-inline: var(--v4-field-inline);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: var(--v4-control-surface);
  color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.field[data-size="md"] {
  --v4-field-height: var(--v4-size-control-md);
  --v4-field-inline: var(--v4-space-control-inline-md);
  --v4-field-nested: var(--v4-size-nested-md);
}
.field[data-size="lg"] {
  --v4-field-height: var(--v4-size-control-lg);
  --v4-field-inline: var(--v4-space-control-inline);
  --v4-field-nested: var(--v4-size-nested-lg);
}
.field::placeholder,
.field ::placeholder {
  color: var(--v4-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field:has([data-field-control]:focus-visible, .field:is(:focus-visible, [aria-expanded="true"])) {
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field:has(:is([data-field-control], .field)[aria-invalid="true"]) {
  border-color: var(--v4-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid]):has([data-field-control]:focus-visible),
.field:has(
    [data-field-control][aria-invalid="true"]:focus-visible,
    .field[aria-invalid="true"]:is(:focus-visible, [aria-expanded="true"])
  ) {
  border-color: var(--v4-bad);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field:has([data-field-control]:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly], :has([data-field-control][readonly])) {
  background-color: var(--v4-paper);
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox:has(> .trailing) {
  padding-inline-end: var(--v4-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--v4-field-height) - 2 * var(--v4-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--v4-muted);
  pointer-events: none;
}
.chevron {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-control-gap);
  text-align: start;
  white-space: nowrap;
  cursor: pointer;
}
.insetHover {
  --v4-inset-hover-gap: calc(var(--v4-space-2) + var(--v4-size-control-border));
  --v4-inset-hover-rest: var(--v4-control-surface);
  background-repeat: no-repeat;
  background-position: center;
  background-size: calc(100% - 2 * var(--v4-inset-hover-gap))
    calc(100% - 2 * var(--v4-inset-hover-gap));
}
.insetHover:is([data-variant="outline"], [data-variant="secondary"]) {
  --v4-inset-hover-rest: var(--v4-action-outline-surface);
}
@media (hover: hover) {
  .insetHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-inset-hover-rest);
    background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
  }
}
.insetHover[aria-expanded="true"] {
  background-color: var(--v4-inset-hover-rest);
  background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child {
  color: var(--v4-muted);
}
.textarea {
  min-height: calc(2 * var(--v4-space-32));
  field-sizing: content;
  resize: vertical;
}
.searchRow {
  display: flex;
  min-height: var(--v4-size-control-lg);
  align-items: center;
  gap: var(--v4-space-8);
  padding-inline: calc(var(--v4-space-menu-inset) + var(--v4-space-8));
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--v4-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--v4-ink);
  caret-color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
}
.searchRow > input::placeholder {
  color: var(--v4-muted);
}
.searchTrailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  color: var(--v4-muted);
}
.searchRow > input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.focusOutline:focus-visible,
.focusOutlineWithin:has(> :focus-visible) {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: var(--v4-size-focus-ring);
}
.focusOutlineInset:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.selectTrigger {
  width: 100%;
  min-width: 0;
}
.selectTrigger [data-slot="select-value"] {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group[data-variant="toolbar"] {
  gap: var(--v4-space-4);
}
.group[data-variant="spaced"] {
  gap: var(--v4-space-8);
  flex-wrap: wrap;
}
.group[data-variant="toolbar"] > *,
.group[data-variant="spaced"] > * {
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.group[data-variant="toolbar"] > [data-slot="button"],
.group[data-variant="spaced"] > [data-slot="button"] {
  border-width: 1px;
}
:where(.card) {
  --v4-card-inset: var(--v4-space-surface-inset);
  --v4-card-body-inset: var(--v4-card-inset);
  --v4-card-lead: 0px;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: 0;
  background: var(--v4-pop);
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  box-shadow: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  container-type: inline-size;
}
.card[data-size="sm"] {
  --v4-card-inset: var(--v4-space-surface-inset-sm);
}
.card:has(> .cardHeader [data-slot="media"]) {
  --v4-card-lead: calc(var(--v4-size-control-lg) + var(--v4-space-12));
}
.card:has(> .cardHeader [data-slot="media"][data-size="sm"]) {
  --v4-card-lead: calc(var(--v4-size-icon) + var(--v4-space-12));
}
:where(.cardHeader) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--v4-space-4) var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-card-inset);
}
:where(.cardHeading) {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
:where(.cardBody) {
  min-width: 0;
  padding: var(--v4-card-body-inset);
  padding-inline-start: calc(var(--v4-card-body-inset) + var(--v4-card-lead));
}
.cardHeader + .cardBody {
  padding-top: 0;
}
.cardPlain {
  background: var(--v4-surface);
}
.card[data-variant="framed"] > .cardHeader .cardTitleGroup {
  flex: 1;
  align-items: center;
}
.card[data-variant="framed"] > .cardHeader + .cardBody {
  padding-top: var(--v4-card-body-inset);
}
.card[data-variant="framed"] > .cardBody:has(+ .cardFooter) {
  border-bottom: 0;
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  box-shadow: none;
}
.card[data-variant="framed"] > .cardBody + .cardFooter {
  border-top-color: var(--v4-line-soft);
  border-start-start-radius: 0;
  border-start-end-radius: 0;
}
.card[data-variant="framed"][data-flush] > .cardHeader {
  border-bottom: 0;
}
.card[data-variant="framed"][data-flush] > .cardBody {
  padding: 0;
  overflow: hidden;
}
.cardMedia {
  flex: 0 0 auto;
  display: inline-flex;
}
.cardTitleGroup {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  min-width: 0;
  grid-column: 1;
  grid-row: 1 / span 2;
}
.cardCopy {
  flex: 1;
  min-width: 0;
}
.cardHeader > [data-slot="card-title"],
.cardHeader > [data-slot="card-description"] {
  grid-column: 1;
}
.cardDescription {
  color: var(--v4-text2);
  margin-top: var(--v4-space-4);
  overflow-wrap: anywhere;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.cardHeader > [data-slot="card-description"] {
  margin-top: 0;
}
:where(.cardAction) {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  max-width: 100%;
  height: var(--v4-type-title-sm-line-height);
  margin-inline-start: auto;
  grid-column: 2;
  grid-row: 1;
}
:where(.cardFooter) {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-space-12) var(--v4-card-inset);
  padding-inline-start: calc(var(--v4-card-inset) + var(--v4-card-lead));
  border-top: var(--v4-size-control-border) solid var(--v4-line);
  color: var(--v4-text2);
  overflow-wrap: anywhere;
}
.choice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  cursor: pointer;
}
.choiceText {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.choiceTitle {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
  color: var(--v4-ink);
}
.choiceDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
}
.choiceRow {
  align-items: center;
  justify-content: space-between;
  padding-block: 12px;
  border-bottom: 1px solid var(--v4-line-soft);
}
.switch {
  --v4-switch-travel: 16px;
  box-sizing: border-box;
  border: var(--v4-size-control-border) solid var(--v4-muted);
  background-color: var(--v4-switch-off-surface);
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-standard);
}
.switch[data-size="default"] {
  width: 36px;
  height: 20px;
  padding: 2px;
}
.switch[data-size="sm"] {
  --v4-switch-travel: 12px;
  width: 28px;
  height: 16px;
  padding: 2px;
}
.switchThumb {
  width: 14px;
  height: 14px;
  background-color: var(--v4-switch-thumb);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-switch-thumb-line),
    0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
  transition-property: background-color, box-shadow;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.switch[data-size="sm"] > .switchThumb {
  width: 10px;
  height: 10px;
}
.switch[data-state="checked"] {
  border-color: var(--v4-sw-on);
  background-color: var(--v4-sw-on);
}
.switch[data-state="checked"] > .switchThumb {
  background-color: var(--v4-sw-knob-on);
  box-shadow: 0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
}
.radioGroup [data-slot="label"] {
  font-weight: var(--v4-type-body-font-weight);
}
.switch[aria-invalid="true"] {
  border-color: var(--v4-control-invalid-border);
}
.check[data-slot="checkbox"] {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.choiceMark {
  border: var(--v4-size-control-border) solid var(--v4-muted);
  background-color: var(--v4-control-surface);
  color: var(--v4-on-ink);
  transition-property: background-color, border-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.choiceMark:is([data-state="checked"], [data-state="indeterminate"]) {
  border-color: var(--v4-ink);
  background-color: var(--v4-ink);
}
.choiceMark[aria-invalid="true"]:not([data-state="checked"], [data-state="indeterminate"]) {
  border-color: var(--v4-control-invalid-border);
}
.radioDot {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--v4-space-8);
  height: var(--v4-space-8);
  translate: -50% -50%;
  border-radius: 50%;
  background-color: var(--v4-on-ink);
}
.check [data-slot="checkbox-indicator"] > * {
  grid-area: 1 / 1;
}
.check [data-mixed],
.check[data-state="indeterminate"] [data-check] {
  opacity: 0;
  transition: opacity var(--v4-duration-fast) var(--v4-ease-fade);
}
.check[data-state="indeterminate"] [data-mixed] {
  opacity: 1;
}
.progressGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.progress {
  background: var(--v4-line-soft);
}
.progressIndicator {
  background: var(--v4-ink);
}
.progressIndicator[data-tone="warn"] {
  background: var(--v4-warn);
}
.progressIndicator[data-tone="bad"] {
  background: var(--v4-bad);
}
.progress[data-state="indeterminate"] .progressIndicator {
  flex: 0 0 35%;
  /* v4-check-ignore motion-literal -- loader choreography, one owner */
  animation: progressTravel 1.4s ease-in-out infinite;
}
@keyframes progressTravel {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(300%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .progress[data-state="indeterminate"] .progressIndicator {
    animation: none;
    transform: translateX(100%) !important;
  }
}
.separatorLabel {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--v4-muted);
  font-size: 12px;
}
.separatorLabel > [data-slot="separator"] {
  flex: 1;
